/**
 * @event
 * @name scwin.grd_result_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_result_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_result'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: PopUp_FeeCal (조건 미해석) */
        if (columnId === "__rowAct") { if (r["applYn"] === '상장완료') { if (typeof scwin.fnPopUpFeeReport === 'function') { scwin.fnPopUpFeeReport(r["bndApplId"], r["bndListProcsTpCd"], r["bndMktactTpCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.fnPopUpFeeReport (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.fnPopUpFeeReport'); } return; } return; } if (r["bndMktactTpCd"] !== '000') { if (typeof scwin.OpenReqView === 'function') { await scwin.OpenReqView(r["bndApplId"], r["bndListProcsTpCd"], r["bndMktactTpCd"], r["bkbndTpCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.OpenReqView (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.OpenReqView'); } return; }
        if (r["applYn"] === '반송') { if (typeof scwin.OpenRetView === 'function') { await scwin.OpenRetView(r["bndApplId"], r["bndListProcsTpCd"], r["bndMktactTpCd"], r["bkbndTpCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.OpenRetView (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.OpenRetView'); } return; }
        if (typeof scwin.detail === 'function') { scwin.detail(r["stdCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.detail (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.detail'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.oncellclick' });
    }
};


