/**
 * @method
 * @name scwin.grd_result_fmt_bndApplId
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_result_fmt_bndApplId = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_result");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "bndMktactTpCd") ?? '') : '');
        if (v !== '000') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "bndApplId") : '') ?? '') + '</a>'; }
        return String((dl && dl.getCellData ? dl.getCellData(r, "bndApplId") : '') ?? '');
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_result.bndApplId" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.grd_result_fmt_stdCd
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_result_fmt_stdCd = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_result");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "nusualBndTpCd") ?? '') : '');
        if (['3','4'].indexOf(v) >= 0) { return String((dl && dl.getCellData ? dl.getCellData(r, "stdCd") : '') ?? ''); }
        return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "stdCd") : '') ?? '') + '</a>';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_result.stdCd" }); return String(data ?? ''); }
};

