/**
 * @event
 * @name scwin.grd_result_fillAct
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.grd_result_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getTotalRow(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.fillAct' });
    }
};

/**
 * @method
 * @name scwin.searchList
 * @author Inswave
 * @date 2026. 09. 29
 * @param div
 * @returns
 * @hidden N
*/
scwin.searchList = async function (div) {
    /* sdd-asis-lifecycle:begin fn_searchList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.SearchForm || { elements: [] });
    if (div === 'button') {
        $c.util.getComponent('dma_searchListReq').set('pageIndex', "1");
    }
    $c.util.getComponent('dma_searchListReq').set('method', "resultSearch");
    frm.action = '/result/result.do';
    frm.target = '_self';
    await scwin.tx_fn_searchList();
    /* sdd-asis-lifecycle:end */
};


