/**
 * @method
 * @name scwin.fnPopUpFeeReport
 * @author Inswave
 * @date 2026. 09. 29
 * @param bnd_appl_id bnd_list_procs_tp_cd bnd_mktact_tp_cd
 * @returns
 * @hidden N
*/
scwin.fnPopUpFeeReport = function (bnd_appl_id, bnd_list_procs_tp_cd, bnd_mktact_tp_cd) {
    /* sdd-asis-lifecycle:begin fnPopUpFeeReport — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $.ajax({ type: "POST", async: false, url: "/main/fee.do?method=feeFinalView&bnd_appl_id=" + bnd_appl_id + "&bnd_list_procs_tp_cd=" + bnd_list_procs_tp_cd + "&bnd_mktact_tp_cd=" + bnd_mktact_tp_cd, data: {  }, success: async function(data) {
                const result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                const form = (document.newReportForm || { elements: [] });
                $c.util.getComponent('dma_searchListReq').set('nIsurNm', result.isurNm);
                $c.util.getComponent('dma_searchListReq').set('nApplIsuNm', result.applIsuNm);
                $c.util.getComponent('dma_searchListReq').set('nStdCd', result.stdCd);
                for (let i = 1; i < 10; i++) {
                    if (eval("!result.listFee" + i)) {
                        eval("form.nListFee" + i + ".value =''");
                    } else {
                        eval("form.nListFee" + i + ".value =result.listFee" + i);
                    }
                    if (eval("!result.anulfee" + i)) {
                        eval("form.nAnulfee" + i + ".value =''");
                    } else {
                        eval("form.nAnulfee" + i + ".value =result.anulfee" + i);
                    }
                }
                $c.util.getComponent('dma_searchListReq').set('nFeeDepoDd', result.feeDepoDd);
                $c.util.getComponent('dma_searchListReq').set('nIsuDd', result.isuDd);
                await scwin.tx_fnPopUpFeeReport();
            }, error: async function(request, status, error) {
                await $c.win.alert("장애발생.");
                return;
            }, complete: function() {

            } });
    /* sdd-asis-lifecycle:end */
};


